-- Claude Multi schema v1
-- All timestamps are RFC 3339 UTC strings generated by the application.

CREATE TABLE providers (
    id          TEXT PRIMARY KEY,
    kind        TEXT NOT NULL CHECK (kind IN ('ollama', 'anthropic')),
    name        TEXT NOT NULL,
    base_url    TEXT NOT NULL,
    enabled     INTEGER NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE accounts (
    id             TEXT PRIMARY KEY,
    provider_id    TEXT NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    label          TEXT NOT NULL,
    auth_kind      TEXT NOT NULL CHECK (auth_kind IN ('none', 'api_key')),
    status         TEXT NOT NULL DEFAULT 'configured'
                   CHECK (status IN ('unconfigured', 'configured', 'error', 'disabled')),
    status_message TEXT,
    metadata_json  TEXT NOT NULL DEFAULT '{}',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (provider_id, label)
);
CREATE INDEX idx_accounts_provider ON accounts(provider_id);

CREATE TABLE projects (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    description   TEXT NOT NULL DEFAULT '',
    instructions  TEXT NOT NULL DEFAULT '',
    archived      INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE conversations (
    id              TEXT PRIMARY KEY,
    project_id      TEXT REFERENCES projects(id) ON DELETE SET NULL,
    title           TEXT NOT NULL DEFAULT 'New conversation',
    pinned          INTEGER NOT NULL DEFAULT 0,
    archived        INTEGER NOT NULL DEFAULT 0,
    provider_id     TEXT REFERENCES providers(id) ON DELETE SET NULL,
    account_id      TEXT REFERENCES accounts(id) ON DELETE SET NULL,
    model           TEXT,
    summary         TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    last_message_at TEXT
);
CREATE INDEX idx_conversations_project ON conversations(project_id);
CREATE INDEX idx_conversations_last_message ON conversations(archived, last_message_at DESC);
CREATE INDEX idx_conversations_pinned ON conversations(pinned DESC, last_message_at DESC);

CREATE TABLE messages (
    id             TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    seq            INTEGER NOT NULL,
    role           TEXT NOT NULL CHECK (role IN ('system', 'user', 'assistant')),
    content        TEXT NOT NULL DEFAULT '',
    reasoning      TEXT,
    status         TEXT NOT NULL DEFAULT 'complete'
                   CHECK (status IN ('complete', 'streaming', 'error', 'cancelled')),
    error          TEXT,
    provider_id    TEXT,
    account_id     TEXT,
    model          TEXT,
    input_tokens   INTEGER,
    output_tokens  INTEGER,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (conversation_id, seq)
);
CREATE INDEX idx_messages_conversation ON messages(conversation_id, seq);

CREATE TABLE attachments (
    id              TEXT PRIMARY KEY,
    project_id      TEXT REFERENCES projects(id) ON DELETE CASCADE,
    conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,
    message_id      TEXT REFERENCES messages(id) ON DELETE SET NULL,
    name            TEXT NOT NULL,
    mime            TEXT NOT NULL,
    size            INTEGER NOT NULL,
    path            TEXT NOT NULL,
    sha256          TEXT NOT NULL,
    kind            TEXT NOT NULL CHECK (kind IN ('image', 'text', 'file')),
    text_content    TEXT,
    created_at      TEXT NOT NULL
);
CREATE INDEX idx_attachments_project ON attachments(project_id);
CREATE INDEX idx_attachments_conversation ON attachments(conversation_id);
CREATE INDEX idx_attachments_message ON attachments(message_id);

CREATE TABLE tasks (
    id              TEXT PRIMARY KEY,
    project_id      TEXT REFERENCES projects(id) ON DELETE SET NULL,
    conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL,
    name            TEXT NOT NULL,
    instructions    TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'queued'
                    CHECK (status IN ('queued', 'running', 'waiting_for_input', 'paused',
                                      'completed', 'failed', 'cancelled')),
    provider_id     TEXT,
    account_id      TEXT,
    model           TEXT,
    current_step    INTEGER NOT NULL DEFAULT 0,
    error           TEXT,
    retry_count     INTEGER NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    started_at      TEXT,
    completed_at    TEXT
);
CREATE INDEX idx_tasks_status ON tasks(status, updated_at DESC);
CREATE INDEX idx_tasks_project ON tasks(project_id);

CREATE TABLE task_steps (
    id          TEXT PRIMARY KEY,
    task_id     TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    seq         INTEGER NOT NULL,
    title       TEXT NOT NULL,
    instruction TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'queued'
                CHECK (status IN ('queued', 'running', 'completed', 'failed', 'skipped')),
    output      TEXT,
    error       TEXT,
    started_at  TEXT,
    completed_at TEXT,
    UNIQUE (task_id, seq)
);
CREATE INDEX idx_task_steps_task ON task_steps(task_id, seq);

CREATE TABLE checkpoints (
    id         TEXT PRIMARY KEY,
    task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    seq        INTEGER NOT NULL,
    state_json TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX idx_checkpoints_task ON checkpoints(task_id, seq DESC);

CREATE TABLE artifacts (
    id         TEXT PRIMARY KEY,
    task_id    TEXT REFERENCES tasks(id) ON DELETE SET NULL,
    project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
    name       TEXT NOT NULL,
    path       TEXT NOT NULL,
    mime       TEXT NOT NULL,
    size       INTEGER NOT NULL,
    sha256     TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX idx_artifacts_task ON artifacts(task_id);
CREATE INDEX idx_artifacts_project ON artifacts(project_id);

CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE usage_records (
    id            TEXT PRIMARY KEY,
    provider_id   TEXT,
    account_id    TEXT,
    model         TEXT,
    conversation_id TEXT,
    task_id       TEXT,
    input_tokens  INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL
);
CREATE INDEX idx_usage_created ON usage_records(created_at);
CREATE INDEX idx_usage_provider ON usage_records(provider_id, model);

CREATE TABLE execution_logs (
    id         TEXT PRIMARY KEY,
    task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    level      TEXT NOT NULL CHECK (level IN ('debug', 'info', 'warn', 'error')),
    message    TEXT NOT NULL,
    data_json  TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX idx_execution_logs_task ON execution_logs(task_id, created_at);
